{
  "name": "@minidoll/agentkit",
  "version": "0.3.5",
  "type": "module",
  "description": "Tool-agnostic agent collaboration workspace protocol — CLI scaffolder, protocol runtime, and client adapter host",
  "license": "MIT",
  "packageManager": "pnpm@10.33.1",
  "bin": {
    "akit": "dist/bin.js"
  },
  "files": [
    "dist",
    "CHANGELOG.md"
  ],
  "keywords": [
    "agent",
    "cli",
    "scaffold",
    "protocol",
    "hooks",
    "codex",
    "claude-code",
    "cursor",
    "opencode"
  ],
  "exports": {
    "./package.json": "./package.json"
  },
  "engines": {
    "node": ">=20"
  },
  "devEngines": {
    "runtime": {
      "name": "node",
      "version": ">=22.18",
      "onFail": "warn"
    }
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "prepack": "node scripts/build.mjs",
    "lint": "eslint .",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:pack": "node scripts/pack-smoke.mjs",
    "validate": "node scripts/validate.mjs",
    "typecheck": "tsc --noEmit -p packages/protocol/tsconfig.json && tsc --noEmit -p packages/runtime/tsconfig.json && tsc --noEmit -p packages/adapters/tsconfig.json && tsc --noEmit -p packages/core/tsconfig.json && tsc --noEmit -p packages/cli/tsconfig.json && tsc --noEmit -p packages/plugins/core/tsconfig.json && tsc --noEmit -p packages/plugins/dsh/tsconfig.json",
    "akit": "node dist/bin.js",
    "akit:dev": "node --experimental-strip-types packages/cli/src/bin.ts"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.5",
    "@types/node": "^24.0.0",
    "esbuild": "0.28.2",
    "eslint": "^9.39.4",
    "typescript": "^5.8.0",
    "typescript-eslint": "^8.71.2",
    "vitest": "^3.2.0"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}
